import os
import contextlib

@contextlib.contextmanager
def set_environ(name, value):
    old_value = os.environ.get(name)
    os.environ[name] = value

    try:
        yield
    finally:
        if old_value is None:
            del os.environ[name]
        else:
            os.environ[name] = old_value

def check():
    test_var = 'TORNADO_TEST_VAR_BUG_CHECK'
