import os

class MockWriter:
    def __init__(self, fd):
        self._fd = fd

    def close(self):
        self._fd.close()

class MockTestCase:
    def __init__(self):
        self._writer = None

    def setUp(self):
        r, w = os.pipe()
        os.close(r) # Not needed for this test
        self.writer_fd = os.fdopen(w, 'w')
        self._writer = MockWriter(self.writer_fd)

    def tearDown(self):
        if self._writer:
            self._writer.close() # This will be the second close

    def _testNoWriter(self):
        def stopTest():
            self._writer.close() # First close
        stopTest()

def demonstrate_double_close():
    test = MockTestCase()
    try:
        test.setUp()
        test._testNoWriter()
        test.tearDown()
    except ValueError as e:
        if 'closed file' in str(e):
            print("CONFIRMED")
            return
    except Exception:
        # Any other exception means the test setup is wrong
        pass
    finally:
        # Ensure the file descriptor is closed if an exception occurred before tearDown
        if not test.writer_fd.closed:
            test.writer_fd.close()

    print("REFUTED")

demonstrate_double_close()

