class Field:
    def __init__(self, min_length=None, max_length=None):
        self.min_length = min_length
        self.max_length = max_length
        self.error_messages = {'min_length': 'min', 'max_length': 'max'}

    def clean(self, value):
        # Simplified version of Django's CharField.clean
        # In reality, it would call to_python, which stringifies the list.
        str_value = str(value)
        errors = []
        # Django forms validate min_length before max_length
        if self.min_length is not None and len(str_value) < self.min_length:
            errors.append(self.error_messages['min_length'])
        if self.max_length is not None and len(str_value) > self.max_length:
            errors.append(self.error_messages['max_length'])
        return errors

class Form:
    def __init__(self, data):
        self.data = data
        self.fields = {
            'field1': Field(min_length=1, max_length=3),
        }
        self.errors = []

    def is_valid(self):
        for name, field in self.fields.items():
            value = self.data.get(name)
            if value is not None:
                field_errors = field.clean(value)
                if field_errors:
                    self.errors.extend(field_errors)
        return not self.errors

