import datetime
import decimal

# Simplified mock of _object_to_data based on DRF < 1.0
def _object_to_data(obj, resource=None):
    if not resource:
        return str(obj.pk)

    fields = getattr(resource, 'fields', ())
    ret = {}
    field_names = []
    for field in fields:
        if isinstance(field, str):
            field_names.append(field)
        elif isinstance(field, tuple):
            field_names.append(field[0])

    for field_name in field_names:
        attr = getattr(obj, field_name)

        # Check for nested resource definition
        # In the original code, `filter` returns an iterator.
        # In Python 3, `filter` is an iterator. In Python 2, it could be a list
        # but let's assume it's used as an iterator.
        nested_filter = filter(lambda f: isinstance(f, tuple) and f[0] == field_name, fields)

        # next() consumes from the iterator. list() would show all items.
        try:
            nested = next(nested_filter)
        except StopIteration:
            nested = None

        if nested:
            nested_fields = nested[1]
            new_resource = type('Resource', (object,), {'fields': nested_fields})()
            ret[field_name] = _object_to_data(attr, new_resource)
        else:
            if isinstance(attr, (datetime.datetime, datetime.date)):
                ret[field_name] = attr
            elif isinstance(attr, decimal.Decimal):
                ret[field_name] = str(attr)
            elif hasattr(attr, 'pk'): # simplified is_model check
                ret[field_name] = attr.pk
            else:
                ret[field_name] = attr
    return ret

